// Simple application for agent to work on
// Enhanced with security best practices, error handling, and input validation

const express = require('express');
const helmet = require('helmet');
const rateLimit = require('express-rate-limit');
const bodyParser = require('body-parser');
const app = express();

// Apply security headers using helmet
app.use(helmet());

// Configure rate limiting to prevent brute-force attacks
const limiter = rateLimit({
  windowMs: 15 * 60 * 1000, // 15 minutes
  max: 100, // limit each IP to 100 requests per windowMs
  standardHeaders: true,
  legacyHeaders: false,
  message: 'Too many requests, please try again later.'
});
app.use(limiter);

// Parse JSON bodies safely
app.use(bodyParser.json({
  limit: '10kb', // Limit body size to prevent DoS attacks
  strict: true   // Only parse JSON, not other content types
}));

// Global error handler middleware
app.use((err, req, res, next) => {
  console.error(err.stack);

  // Send appropriate status code and error message
  const status = err.status || 500;
  const message = process.env.NODE_ENV === 'production' 
    ? (status === 500 ? 'Internal Server Error' : err.message) 
    : err.message;

  res.status(status).json({
    error: {
      message: message,
      status: status,
      timestamp: new Date().toISOString()
    }
  });
});

// Health endpoint with input validation
app.get('/health', (req, res) => {
  // Basic validation - ensure query params are safe
  if (Object.keys(req.query).length > 0) {
    // If unexpected query params are provided, ignore them but don't crash
    console.warn('Unexpected query parameters in /health endpoint');
  }

  res.json({ 
    status: 'ok', 
    timestamp: new Date().toISOString(),
    environment: process.env.NODE_ENV || 'development'
  });
});

// Users endpoint with input validation
app.get('/users', (req, res) => {
  // Validate query parameters if present
  if (Object.keys(req.query).length > 0) {
    // Only allow specific, safe query parameters
    const allowedParams = ['page', 'limit', 'sort'];
    const invalidParams = Object.keys(req.query).filter(p => !allowedParams.includes(p));

    if (invalidParams.length > 0) {
      return res.status(400).json({
        error: {
          message: `Invalid query parameters: ${invalidParams.join(', ')}`,
          status: 400,
          timestamp: new Date().toISOString()
        }
      });
    }
  }

  // In a real app, this would come from a database
  res.json([
    { id: 1, name: 'Alice', email: 'alice@example.com' },
    { id: 2, name: 'Bob', email: 'bob@example.com' },
  ]);
});

// Route not found handler
app.use((req, res) => {
  res.status(404).json({
    error: {
      message: 'Resource not found',
      status: 404,
      timestamp: new Date().toISOString()
    }
  });
});

// Start server with proper error handling
const PORT = process.env.PORT || 3000;

const server = app.listen(PORT, () => {
  console.log(`Server running on port ${PORT}`);
  console.log(`Environment: ${process.env.NODE_ENV || 'development'}`);
});

// Handle server errors
server.on('error', (error) => {
  if (error.syscall !== 'listen') {
    throw error;
  }

  const address = server.address();
  const bind = typeof address === 'string' ? 'pipe ' + address : 'port ' + address;

  // Handle specific listen errors with friendly messages
  switch (error.code) {
    case 'EACCES':
      console.error(`${bind} requires elevated privileges`);
      process.exit(1);
      break;
    case 'ADDRINUSE':
      console.error(`${bind} is already in use`);
      process.exit(1);
      break;
    default:
      throw error;
  }
});

module.exports = app;

