// Simple application for agent to work on
// Enhanced with error handling, input validation, and security best practices

const express = require('express');
const app = express();
const { default: helmet } = require('helmet'); // For security headers
const rateLimit = require('express-rate-limit'); // For rate limiting
const xss = require('xss-clean'); // For XSS protection
const hpp = require('hpp'); // For HTTP Parameter Pollution protection
const cors = require('cors'); // For proper CORS handling

// Initialize security middleware
app.use(helmet()); // Set security-related HTTP headers
app.use(express.json({ limit: '10kb' })); // Limit body size and parse JSON
app.use(express.urlencoded({ extended: true, limit: '10kb' })); // Limit URL-encoded bodies
app.use(xss()); // Sanitize user input to prevent XSS
app.use(hpp()); // Prevent HTTP Parameter Pollution attacks
app.use(cors({ origin: process.env.CORS_ORIGIN || 'http://localhost:3000', credentials: true })); // Proper CORS configuration

// Rate limiting to prevent brute-force attacks
const limiter = rateLimit({
  windowMs: 15 * 60 * 1000, // 15 minutes
  max: 100, // Limit each IP to 100 requests per windowMs
  message: 'Too many requests from this IP, please try again after 15 minutes'
});
app.use('/api', limiter); // Apply rate limiting to API routes

// Custom error handling middleware
class AppError extends Error {
  constructor(message, statusCode) {
    super(message);
    this.statusCode = statusCode;
    this.status = `${statusCode}`.startsWith('4') ? 'fail' : 'error';
    this.isOperational = true;

    Error.captureStackTrace(this, this.constructor);
  }
}

// Global error handling middleware
app.all('*', (req, res, next) => {
  next(new AppError(`Can't find ${req.originalUrl} on this server!`, 404));
});

app.use((err, req, res, next) => {
  err.statusCode = err.statusCode || 500;
  err.status = err.status || 'error';

  // Development mode: send detailed error information
  // Production mode: send generic error message
  const response = {
    status: err.status,
    message: err.message,
    ...(process.env.NODE_ENV !== 'production' && { stack: err.stack }),
    ...(process.env.NODE_ENV === 'development' && { error: err })
  };

  // If it's a validation error, provide more specific details
  if (err.name === 'ValidationError') {
    response.message = Object.values(err.errors).map(val => val.message);
  }

  res.status(err.statusCode).json(response);
});

// Health check endpoint with input validation
app.get('/health', (req, res, next) => {
  try {
    // Basic validation if query parameters are added later
    if (req.query.timestamp && isNaN(Date.parse(req.query.timestamp))) {
      return next(new AppError('Invalid timestamp parameter', 400));
    }

    res.json({ 
      status: 'ok', 
      timestamp: new Date().toISOString(),
      ...(process.env.NODE_ENV === 'development' && { environment: process.env.NODE_ENV })
    });
  } catch (err) {
    next(err);
  }
});

// Users endpoint with input validation
app.get('/users', (req, res, next) => {
  try {
    // Validate query parameters if filtering is implemented
    if (req.query.id && isNaN(parseInt(req.query.id))) {
      return next(new AppError('Invalid user ID format', 400));
    }

    // In a real application, this would come from a database
    const users = [
      { id: 1, name: 'Alice', email: 'alice@example.com' },
      { id: 2, name: 'Bob', email: 'bob@example.com' },
    ];

    // Filter users based on query parameters (if implemented)
    let filteredUsers = [...users];

    if (req.query.id) {
      const userId = parseInt(req.query.id);
      filteredUsers = users.filter(user => user.id === userId);

      if (filteredUsers.length === 0) {
        return next(new AppError('User not found', 404));
      }
    }

    res.json({
      status: 'success',
      results: filteredUsers.length,
      data: {
        users: filteredUsers
      }
    });
  } catch (err) {
    next(err);
  }
});

// Example endpoint demonstrating input validation
app.post('/api/data', (req, res, next) => {
  try {
    const { name, email } = req.body;

    // Validate presence of required fields
    if (!name || !email) {
      return next(new AppError('Name and email are required fields', 400));
    }

    // Validate email format
    const emailRegex = /^[^\s@]+@[^\s@]+\.[^\s@]+$/;
    if (!emailRegex.test(email)) {
      return next(new AppError('Invalid email format', 400));
    }

    // Validate name length
    if (name.length > 100) {
      return next(new AppError('Name is too long (max 100 characters)', 400));
    }

    // Process valid data (in real app, this would save to database)
    res.status(201).json({
      status: 'success',
      data: {
        acknowledged: true,
        createdAt: new Date().toISOString(),
        name,
        email
      }
    });
  } catch (err) {
    next(err);
  }
});

app.listen(3000, () => {
  console.log('Server running on port 3000');
});

module.exports = app;

