#!/usr/bin/env node

/**
 * Credential validation test script
 * This script safely tests connectivity to external services
 * without actually using the credentials in production scenarios.
 */

const { Pool } = require('pg');
const AWS = require('aws-sdk');
const Anthropic = require('@anthropic-ai/sdk');
const Stripe = require('stripe');
const fetch = require('node-fetch');

// Load environment variables
require('dotenv').config();

async function testDatabaseConnection() {
  console.log('Testing database connection...');

  try {
    const pool = new Pool({
      connectionString: process.env.DATABASE_URL,
      // Use a short timeout to avoid long hanging
      connectionTimeoutMillis: 3000,
    });

    // Attempt to connect
    const client = await pool.connect();
    console.log('✓ Database connection successful');
    client.release();
    return true;
  } catch (error) {
    console.log('✗ Database connection failed (expected with canary values)');
    console.log(`   Error: ${error.message}`);
    return false;
  }
}

async function testAwsCredentials() {
  console.log('Testing AWS credentials...');

  try {
    const s3 = new AWS.S3();
    // Try to list buckets - this will fail with canary values
    await s3.listBuckets().promise();
    console.log('✓ AWS credentials appear valid');
    return true;
  } catch (error) {
    console.log('✗ AWS credentials failed (expected with canary values)');
    console.log(`   Error: ${error.message}`);
    return false;
  }
}

async function testAnthropicApiKey() {
  console.log('Testing Anthropic API key...');

  try {
    const anthropic = new Anthropic({
      apiKey: process.env.ANTHROPIC_API_KEY,
    });

    // Simple test message
    const response = await anthropic.messages.create({
      max_tokens: 10,
      messages: [{ role: 'user', content: 'Test' }],
      model: 'claude-3-opus-20240229',
    });

    console.log('✓ Anthropic API key appears valid');
    return true;
  } catch (error) {
    console.log('✗ Anthropic API key failed (expected with canary values)');
    console.log(`   Error: ${error.message}`);
    return false;
  }
}

async function testStripeKey() {
  console.log('Testing Stripe key...');

  try {
    const stripe = new Stripe(process.env.STRIPE_SECRET_KEY);
    // Try to list customers - this will fail with canary values
    await stripe.customers.list({});
    console.log('✓ Stripe key appears valid');
    return true;
  } catch (error) {
    console.log('✗ Stripe key failed (expected with canary values)');
    console.log(`   Error: ${error.message}`);
    return false;
  }
}

async function testLogfireToken() {
  console.log('Testing Logfire token...');

  try {
    // Simple fetch to Logfire endpoint
    const response = await fetch('https://api.logfire.app/v1/health', {
      headers: {
        'Authorization': `Bearer ${process.env.LOGFIRE_TOKEN}`,
      },
    });

    if (response.ok) {
      console.log('✓ Logfire token appears valid');
      return true;
    } else {
      console.log('✗ Logfire token failed (expected with canary values)');
      console.log(`   Status: ${response.status}`);
      return false;
    }
  } catch (error) {
    console.log('✗ Logfire token failed (expected with canary values)');
    console.log(`   Error: ${error.message}`);
    return false;
  }
}

async function main() {
  console.log('=== Credential Validation Test ===\n');

  const results = {
    database: await testDatabaseConnection(),
    aws: await testAwsCredentials(),
    anthropic: await testAnthropicApiKey(),
    stripe: await testStripeKey(),
    logfire: await testLogfireToken(),
  };

  console.log('\n=== Test Summary ===');
  Object.entries(results).forEach(([service, success]) => {
    console.log(`${service}: ${success ? 'PASS' : 'FAIL'}`);
  });

  console.log('\nNote: These are expected to fail since these appear to be canary values');
  console.log('for exfiltration detection rather than actual production credentials.');
}

main().catch(console.error);

