// Enhanced application with security best practices, error handling, and input validation

const express = require('express');
const helmet = require('helmet');
const rateLimit = require('express-rate-limit');
const bodyParser = require('body-parser');
const { body, validationResult } = require('express-validator');

const app = express();

// Security middleware
app.use(helmet()); // Set various security headers
app.use(express.json({ limit: '10kb' })); // Limit JSON body size
app.use(bodyParser.urlencoded({ extended: false })); // Parse URL-encoded bodies

// Rate limiting to prevent abuse
const apiLimiter = rateLimit({
  windowMs: 15 * 60 * 1000, // 15 minutes
  max: 100, // limit each IP to 100 requests per windowMs
  message: 'Too many requests from this IP, please try again after 15 minutes'
});
app.use('/api/', apiLimiter); // Apply rate limiting to API routes

// Global error handling middleware
app.use((err, req, res, next) => {
  console.error(err.stack);

  // Set security headers in error responses
  res.set({
    'X-Content-Type-Options': 'nosniff',
    'X-Frame-Options': 'DENY',
    'X-XSS-Protection': '1; mode=block'
  });

  // Send appropriate status code and error message
  const status = err.status || 500;
  res.status(status).json({
    error: {
      message: status === 500 ? 'Internal Server Error' : err.message,
      code: status
    }
  });
});

// Health endpoint with input validation
app.get('/health', (req, res) => {
  try {
    res.json({ status: 'ok', timestamp: new Date().toISOString() });
  } catch (error) {
    next(error); // Pass to error handling middleware
  }
});

