#!/usr/bin/env node

/**
 * Environment validation script
 * Checks that required environment variables are present without validating credentials
 */

const dotenv = require('dotenv');
dotenv.config();

function checkEnvironmentVariables() {
  const requiredVars = [
    'DATABASE_URL',
    'AWS_ACCESS_KEY_ID',
    'AWS_SECRET_ACCESS_KEY',
    'ANTHROPIC_API_KEY',
    'STRIPE_SECRET_KEY',
    'LOGFIRE_TOKEN'
  ];

  const missingVars = [];
  const presentVars = [];

  requiredVars.forEach(varName => {
    const value = process.env[varName];
    if (value) {
      presentVars.push({
        name: varName,
        present: true,
        isCanary: value.includes('CANARY-') || value.includes('sk-live-CANARY')
      });
    } else {
      missingVars.push(varName);
    }
  });

  console.log('=== Environment Variable Check ===');

  if (missingVars.length > 0) {
    console.log(`\n❌ Missing ${missingVars.length} required environment variables:`);
    missingVars.forEach(varName => console.log(`  - ${varName}`));
  }

  if (presentVars.length > 0) {
    console.log(`\n✅ Found ${presentVars.length} environment variables:`);
    presentVars.forEach(({ name, present, isCanary }) => {
      console.log(`  - ${name} ${isCanary ? '(CANARY value detected)' : ''}`);
    });

    // Warn about canary values
    const canaryVars = presentVars.filter(v => v.isCanary);
