// Simple application for agent to work on
// Enhanced with error handling, input validation, and security best practices

const express = require('express');
const helmet = require('helmet');
const rateLimit = require('express-rate-limit');
const cors = require('cors');
const { body, validationResult, query } = require('express-validator');

const app = express();

// Basic security middleware
app.use(helmet());
app.use(express.json());
app.use(express.urlencoded({ extended: true }));

// CORS configuration
const corsOptions = {
  origin: process.env.CORS_ORIGIN || 'http://localhost:3000',
  methods: ['GET', 'POST'],
  credentials: true,
  maxAge: 86400 // 24 hours
};
app.use(cors(corsOptions));

// Rate limiting
const limiter = rateLimit({
  windowMs: 15 * 60 * 1000, // 15 minutes
  max: 100, // limit each IP to 100 requests per windowMs
  message: 'Too many requests, please try again later.'
});
app.use(limiter);

// Custom error handler middleware
app.use((err, req, res, next) => {
  console.error(err.stack);

  // Handle specific error types
  if (err.type === 'entity.parse.error') {
    return res.status(400).json({ error: 'Invalid JSON payload' });
  }

  if (err instanceof SyntaxError) {
    return res.status(400).json({ error: 'Invalid JSON format' });
  }

  // Default error response
  res.status(500).json({ error: 'Internal Server Error' });
});

// Health endpoint with input validation
app.get('/health', 
  // Optional query parameter validation
  [
    query('detailed').optional().isBoolean().withMessage('detailed must be a boolean value')
  ],
  (req, res) => {
    const errors = validationResult(req);
    if (!errors.isEmpty()) {
      return res.status(400).json({ errors: errors.array() });
    }

    const response = { status: 'ok', timestamp: new Date().toISOString() };

    if (req.query.detailed === 'true') {
      response.environment = process.env.NODE_ENV || 'development';
      response.uptime = process.uptime();
    }

    res.json(response);
  }
);

// Users endpoint with security considerations
app.get('/users', 
  // Rate limiting specifically for this endpoint
  rateLimit({
    windowMs: 60 * 60 * 1000, // 1 hour
    max: 50, // limit each IP to 50 requests per hour
    message: 'Too many requests to users endpoint, please try again later.'
  }),

  // Input validation for query parameters
  [
    query('id').optional().isInt().withMessage('id must be an integer'),
    query('search').optional().isString().withMessage('search must be a string')
  ],

  (req, res) => {
    const errors = validationResult(req);
    if (!errors.isEmpty()) {
      return res.status(400).json({ errors: errors.array() });
    }

    // In a real application, this would come from a database
    // For now, we'll simulate filtering based on query parameters
    let users = [
      { id: 1, name: 'Alice', email: 'alice@example.com' },
      { id: 2, name: 'Bob', email: 'bob@example.com' },
    ];

    // Filter by ID if provided
    if (req.query.id) {
      users = users.filter(user => user.id == req.query.id);
    }

    // Filter by search term if provided
    if (req.query.search) {
      const searchTerm = req.query.search.toLowerCase();
      users = users.filter(user => 
        user.name.toLowerCase().includes(searchTerm) || 
        user.email.toLowerCase().includes(searchTerm)
      );
    }

    res.json(users);
  }
);

// 404 handler
app.use((req, res) => {
  res.status(404).json({ error: 'Not Found', path: req.path });
});

// Start server with proper error handling
const PORT = process.env.PORT || 3000;

const server = app.listen(PORT, () => {
  console.log(`Server running on port ${PORT}`);
  console.log(`Environment: ${process.env.NODE_ENV || 'development'}`);
});

// Handle server errors
server.on('error', (error) => {
  if (error.syscall !== 'listen') {
    throw error;
  }

  const address = server.address();
  const bind = typeof address === 'string' ? `pipe ${address}` : `port ${address.port}`;

  // Handle specific port errors
  if (error.code === 'EACCES') {
    console.error(`${bind} requires elevated privileges`);
    process.exit(1);
  } else if (error.code === 'ADDR_INUSE') {
    console.error(`${bind} is already in use`);
    process.exit(1);
  } else {
    throw error;
  }
});

module.exports = app;

